// Krunker Strike's engine tables (shared/include/strike_rules.h): Krunker v10.0.2's weapon, class
// and mode tables with FRVR's Strike values (strike_data.c, generated by tools/strike/gen_rules.py)
// applied, and Strike's default lobby config. Built once on first use, read-only afterwards; only a
// process whose flavor carries rules (FLAVOR_STRIKE) ever builds them.
#include <strike_rules.h>
#include <game_config.h>
#include <ruleset.h>
#include <strike_maps.h> // the map pool: Ruleset.rotation_maps

#include <math.h>
#include <stdatomic.h>
#include <string.h>

const StrikeRules *strike_rules(void) { return &g_strike_rules; }

static const StrikeRules *or_default(const StrikeRules *rules) { return rules ? rules : &g_strike_rules; }

const StrikeClass *strike_class(const StrikeRules *rules, const int class_id) {
    rules = or_default(rules);
    for (size_t i = 0; i < rules->class_count; i++) {
        if (rules->classes[i].id == class_id) return &rules->classes[i];
    }
    return NULL;
}

const StrikeWeapon *strike_weapon(const StrikeRules *rules, const int weapon_id) {
    rules = or_default(rules);
    for (size_t i = 0; i < rules->weapon_count; i++) {
        if (rules->weapons[i].id == weapon_id) return &rules->weapons[i];
    }
    return NULL;
}

const StrikeMode *strike_mode(const StrikeRules *rules, const int mode_id) {
    rules = or_default(rules);
    for (size_t i = 0; i < rules->mode_count; i++) {
        if (rules->modes[i].mode_id == mode_id) return &rules->modes[i];
    }
    return NULL;
}

const StrikeConfigDefault *strike_config_default(const StrikeRules *rules, const char *var) {
    rules = or_default(rules);
    if (!var) return NULL;
    for (size_t i = 0; i < rules->config_default_count; i++) {
        if (!strcmp(rules->config_defaults[i].var, var)) return &rules->config_defaults[i];
    }
    return NULL;
}

const StrikeBind *strike_bind(const StrikeRules *rules, const char *bind, const int index) {
    rules = or_default(rules);
    if (!bind) return NULL;
    for (size_t i = 0; i < rules->bind_count; i++) {
        if (rules->binds[i].index == index && !strcmp(rules->binds[i].bind, bind)) return &rules->binds[i];
    }
    return NULL;
}

const StrikeSetting *strike_setting(const StrikeRules *rules, const char *key) {
    rules = or_default(rules);
    if (!key) return NULL;
    for (size_t i = 0; i < rules->setting_count; i++) {
        if (!strcmp(rules->settings[i].key, key)) return &rules->settings[i];
    }
    return NULL;
}

